/* usage: *    MATCH_DROP(t, a) and MATCH_DROP(t, b) must both be proven false *    before MATCH_EQ(t, a, b) is used. */#define	MATCH_DROP(table, c) ( c & 0200 || table[c] == 0 )		#define MATCH_EQ(table, a, b) ( a == b || table[a] == table[b] )#define MATCH_LS_EQ(table, a, b) ( a <= b || table[a] <= table[b] )#define MATCH_LS(table, a, b) ( a < b || table[a] < table[b] )#define	MATCH_CMP(table, a, b) (table[a] - table[b])